declare(strict_types=1); namespace OCA\Shortcut\Controller; use OCP\AppFramework\Controller; use OCP\AppFramework\Http\DataResponse; use OCP\AppFramework\Http\Attribute\NoAdminRequired; use OCP\Files\IRootFolder; use OCP\Files\NotFoundException; use OCP\Files\StorageNotAvailableException; use OCP\IRequest; use OCP\IUserSession; use OCP\IURLGenerator; class ShortcutController extends Controller { public function __construct( string $appName, IRequest $request, private IRootFolder $rootFolder, private IUserSession $userSession, private IURLGenerator $urlGenerator, ) { parent::__construct($appName, $request); } #[NoAdminRequired] public function create( int $targetId, string $targetPath, string $destFolderPath, string $shortcutName, string $targetType = "file" ): DataResponse { $user = $this->userSession->getUser(); if (!$user) { return new DataResponse(["error" => "Unauthenticated"], 401); } $userFolder = $this->rootFolder->getUserFolder($user->getUID()); try { $destPath = trim($destFolderPath, "/"); $destFolder = ($destPath === "") ? $userFolder : $userFolder->get($destPath); if (!$destFolder instanceof \OCP\Files\Folder) { return new DataResponse(["error" => "Destination is not a folder"], 400); } $createdFile = $this->createShortcutFile( $destFolder, $userFolder, $targetId, $targetPath, $shortcutName, $targetType ); return new DataResponse([ "success" => true, "file" => [ "id" => $createdFile->getId(), "name" => $createdFile->getName(), "path" => "/" . ltrim($userFolder->getRelativePath($createdFile->getPath()), "/"), ] ]); } catch (\Exception $e) { return new DataResponse(["error" => $e->getMessage()], 500); } } #[NoAdminRequired] public function createBatch( array $items, string $destFolderPath ): DataResponse { $user = $this->userSession->getUser(); if (!$user) { return new DataResponse(["error" => "Unauthenticated"], 401); } $userFolder = $this->rootFolder->getUserFolder($user->getUID()); try { $destPath = trim($destFolderPath, "/"); $destFolder = ($destPath === "") ? $userFolder : $userFolder->get($destPath); if (!$destFolder instanceof \OCP\Files\Folder) { return new DataResponse(["error" => "Destination is not a folder"], 400); } $createdList = []; foreach ($items as $item) { $targetId = (int)($item["targetId"] ?? 0); $targetPath = (string)($item["targetPath"] ?? ""); $shortcutName = (string)($item["shortcutName"] ?? "item"); $targetType = (string)($item["targetType"] ?? "file"); if ($targetId <= 0 || empty($targetPath)) { continue; } $newFile = $this->createShortcutFile( $destFolder, $userFolder, $targetId, $targetPath, $shortcutName, $targetType ); $createdList[] = [ "id" => $newFile->getId(), "name" => $newFile->getName(), "path" => "/" . ltrim($userFolder->getRelativePath($newFile->getPath()), "/"), ]; } return new DataResponse([ "success" => true, "count" => count($createdList), "files" => $createdList, ]); } catch (\Exception $e) { return new DataResponse(["error" => $e->getMessage()], 500); } } #[NoAdminRequired] public function resolveFile(int $fileId): DataResponse { $user = $this->userSession->getUser(); if (!$user) { return new DataResponse(["error" => "Unauthenticated"], 401); } $userFolder = $this->rootFolder->getUserFolder($user->getUID()); try { $nodes = $userFolder->getById($fileId); if (empty($nodes)) { return new DataResponse(["error" => "Shortcut file not found"], 404); } $shortcutFile = $nodes[0]; if (!$shortcutFile instanceof \OCP\Files\File) { return new DataResponse(["error" => "Specified item is not a file"], 400); } $content = $shortcutFile->getContent(); $meta = $this->parseShortcutContent($content); if ($meta === null) { return new DataResponse(["error" => "Invalid shortcut format"], 400); } $targetId = $meta["targetId"] ?? 0; $fallbackPath = $meta["targetPath"] ?? ""; $expectedName = $meta["targetName"] ?? ""; if ($targetId > 0) { try { $targetNodes = $userFolder->getById($targetId); if (!empty($targetNodes)) { $selectedNode = $this->pickBestMatchingNode($targetNodes, $userFolder, $fallbackPath); $relPath = "/" . ltrim($userFolder->getRelativePath($selectedNode->getPath()), "/"); $parentDir = (dirname($relPath) === "/" || dirname($relPath) === ".") ? "/" : dirname($relPath); return new DataResponse([ "success" => true, "target" => [ "id" => $selectedNode->getId(), "path" => $relPath, "parentDir" => $parentDir, "type" => ($selectedNode instanceof \OCP\Files\Folder) ? "dir" : "file", "name" => $selectedNode->getName(), "shortcutFileId" => $shortcutFile->getId(), "shortcutFileName" => $shortcutFile->getName(), ] ]); } } catch (StorageNotAvailableException) { return new DataResponse(["error" => "リンク先の外部ストレージが一時的に利用できません"], 503); } } if ($fallbackPath !== "") { $cleanPath = "/" . ltrim($fallbackPath, "/"); try { $node = $userFolder->get(ltrim($cleanPath, "/")); $relPath = "/" . ltrim($userFolder->getRelativePath($node->getPath()), "/"); $parentDir = (dirname($relPath) === "/" || dirname($relPath) === ".") ? "/" : dirname($relPath); return new DataResponse([ "success" => true, "target" => [ "id" => $node->getId(), "path" => $relPath, "parentDir" => $parentDir, "type" => ($node instanceof \OCP\Files\Folder) ? "dir" : "file", "name" => $node->getName(), "shortcutFileId" => $shortcutFile->getId(), "shortcutFileName" => $shortcutFile->getName(), ] ]); } catch (NotFoundException | StorageNotAvailableException) { } } return new DataResponse([ "error" => "リンク先が見つかりません (削除または移動された可能性があります)", "targetNotFound" => true, "shortcutFileId" => $shortcutFile->getId(), "shortcutFileName" => $shortcutFile->getName(), "lastKnownPath" => $fallbackPath, ], 404); } catch (\Exception $e) { return new DataResponse(["error" => $e->getMessage()], 500); } } #[NoAdminRequired] public function resolve(int $targetId): DataResponse { $user = $this->userSession->getUser(); if (!$user) { return new DataResponse(["error" => "Unauthenticated"], 401); } $userFolder = $this->rootFolder->getUserFolder($user->getUID()); try { $nodes = $userFolder->getById($targetId); if (empty($nodes)) { return new DataResponse(["error" => "Target not found"], 404); } $node = $nodes[0]; $relPath = "/" . ltrim($userFolder->getRelativePath($node->getPath()), "/"); return new DataResponse([ "success" => true, "target" => [ "id" => $node->getId(), "path" => $relPath, "type" => ($node instanceof \OCP\Files\Folder) ? "dir" : "file", "name" => $node->getName(), ] ]); } catch (\Exception $e) { return new DataResponse(["error" => $e->getMessage()], 500); } } #[NoAdminRequired] public function deleteShortcut(int $fileId): DataResponse { $user = $this->userSession->getUser(); if (!$user) { return new DataResponse(["error" => "Unauthenticated"], 401); } $userFolder = $this->rootFolder->getUserFolder($user->getUID()); try { $nodes = $userFolder->getById($fileId); if (empty($nodes)) { return new DataResponse(["error" => "File not found"], 404); } $file = $nodes[0]; $file->delete(); return new DataResponse(["success" => true]); } catch (\Exception $e) { return new DataResponse(["error" => $e->getMessage()], 500); } } private function createShortcutFile( \OCP\Files\Folder $destFolder, \OCP\Files\Folder $userFolder, int $targetId, string $targetPath, string $shortcutName, string $targetType ): \OCP\Files\File { $cleanName = trim(preg_replace("/[\\\\\\/*?:\"<>|]/", "_", $shortcutName)); if (!str_ends_with(strtolower($cleanName), ".url")) { $fileName = $cleanName . ".url"; } else { $fileName = $cleanName; } $baseName = pathinfo($fileName, PATHINFO_FILENAME); $ext = pathinfo($fileName, PATHINFO_EXTENSION); $candidateName = $fileName; $counter = 1; while ($destFolder->nodeExists($candidateName)) { $candidateName = "{$baseName} ({$counter}).{$ext}"; $counter++; } $fileName = $candidateName; $webDir = ($targetType === "dir") ? $targetPath : dirname($targetPath); $webUrl = $this->urlGenerator->linkToRouteAbsolute("files.view.index", [ "dir" => $webDir, ]); $content = "[InternetShortcut]\r\n" . "URL={$webUrl}\r\n" . "IDList=\r\n" . "[NextcloudShortcut]\r\n" . "Version=1.1\r\n" . "TargetId={$targetId}\r\n" . "TargetPath={$targetPath}\r\n" . "TargetType={$targetType}\r\n" . "TargetName=" . basename($targetPath) . "\r\n" . "CreatedAt=" . date("c") . "\r\n"; $newFile = $destFolder->newFile($fileName); $newFile->putContent($content); return $newFile; } private function pickBestMatchingNode(array $nodes, \OCP\Files\Folder $userFolder, string $expectedPath): \OCP\Files\Node { if (count($nodes) === 1) { return $nodes[0]; } $expectedClean = "/" . ltrim($expectedPath, "/"); $expectedParts = explode("/", trim($expectedClean, "/")); $expectedTopMount = $expectedParts[0] ?? ""; foreach ($nodes as $node) { $rel = "/" . ltrim($userFolder->getRelativePath($node->getPath()), "/"); $parts = explode("/", trim($rel, "/")); $topMount = $parts[0] ?? ""; if ($topMount !== "" && $topMount === $expectedTopMount) { return $node; } } return $nodes[0]; } private function parseShortcutContent(string $content): ?array { $meta = []; if (preg_match("/TargetId=(\d+)/i", $content, $m)) { $meta["targetId"] = (int)$m[1]; } if (preg_match("/TargetPath=(.+?)[\r\n]/i", $content, $m)) { $meta["targetPath"] = trim($m[1]); } if (preg_match("/TargetType=(.+?)[\r\n]/i", $content, $m)) { $meta["targetType"] = trim($m[1]); } if (preg_match("/TargetName=(.+?)[\r\n]/i", $content, $m)) { $meta["targetName"] = trim($m[1]); } if (empty($meta)) { if (preg_match("/URL=(.+?)[\r\n]/i", $content, $m)) { $url = trim($m[1]); $parsed = parse_url($url); if (isset($parsed["query"])) { parse_str($parsed["query"], $query); if (isset($query["dir"])) { $meta["targetPath"] = $query["dir"]; $meta["targetType"] = "dir"; } } } } return !empty($meta) ? $meta : null; } }